#include <iostream>
#include <algorithm>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 a, b, c, l;
    cin >> a >> b >> c >> l;

    int64 total = (l + 1) * (l + 2) * (l + 3) / 6;

    auto countInvalid = [&](int64 dominant, int64 other1, int64 other2) {
        int64 result = 0;
        int64 required = other1 + other2 - dominant;

        for (int64 sumOthers = 0; sumOthers <= l; ++sumOthers) {
            int64 minIncrease = max<int64>(0, sumOthers + required);
            int64 choices = l - sumOthers - minIncrease + 1;
            if (choices > 0)
                result += (sumOthers + 1) * choices;
        }
        return result;
    };

    total -= countInvalid(a, b, c);
    total -= countInvalid(b, a, c);
    total -= countInvalid(c, a, b);

    cout << total << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b, c, l;
    cin >> a >> b >> c >> l;

    auto invalidWays = [&](long long longest, long long u, long long v) {
        long long d = u + v - longest;
        long long result = 0;

        for (long long s = 0; s <= l; ++s) {
            long long lower = max(0LL, s + d);
            long long upper = l - s;
            if (lower <= upper)
                result += (s + 1) * (upper - lower + 1);
        }
        return result;
    };

    long long total = (l + 1) * (l + 2) * (l + 3) / 6;

    long long answer = total
        - invalidWays(a, b, c)
        - invalidWays(b, a, c)
        - invalidWays(c, a, b);

    cout << answer << '\n';
    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

using int64 = long long;

int64 countInvalid(int64 side, int64 other1, int64 other2, int64 l) {
    int64 d = other1 + other2 - side;
    int64 ways = 0;

    for (int64 s = 0; s <= l; ++s) {
        int64 lower = max(0LL, s + d);
        int64 upper = l - s;
        if (lower <= upper) {
            ways += (s + 1) * (upper - lower + 1);
        }
    }

    return ways;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 a, b, c, l;
    cin >> a >> b >> c >> l;

    int64 total = (l + 1) * (l + 2) * (l + 3) / 6;
    int64 invalid = countInvalid(a, b, c, l)
                  + countInvalid(b, a, c, l)
                  + countInvalid(c, a, b, l);

    cout << total - invalid << '\n';
    return 0;
}

